typedef struct {int *a; int n, cap;} Vec;
static void vpush(Vec*v,int x){if(v->n==v->cap){v->cap=v->cap?v->cap*2:16;v->a=realloc(v->a,sizeof(int)*v->cap);}v->a[v->n++]=x;}

