      else if(x<rv[K-1]){int p=K-1;while(p>0&&rv[p-1]>x){rv[p]=rv[p-1];ri[p]=ri[p-1];p--;}rv[p]=x;ri[p]=j;}
      double*c=cv+j*K;int*ci=cidx+j*K;int cc=ccnt[j];
      if(cc<K){int p=cc;ccnt[j]=cc+1;while(p>0&&c[p-1]>x){c[p]=c[p-1];ci[p]=ci[p-1];p--;}c[p]=x;ci[p]=i;}
      else if(x<c[K-1]){int p=K-1;while(p>0&&c[p-1]>x){c[p]=c[p-1];ci[p]=ci[p-1];p--;}c[p]=x;ci[p]=i;}
    }
